const colorStoreKey='habit-notebook-colors-v1';function readColorStore(){try{const v=JSON.parse(localStorage.getItem(colorStoreKey));return{saved:Array.isArray(v?.saved)?v.saved.filter(isSoftColor).slice(0,8):[],recent:Array.isArray(v?.recent)?v.recent.filter(isSoftColor).slice(0,8):[]}}catch{return{saved:[],recent:[]}}}function writeColorStore(store){try{localStorage.setItem(colorStoreKey,JSON.stringify(store))}catch{}}
