// Refresh the today marker when the local calendar date changes.
let displayedToday=dateKey(new Date());
function refreshToday(){const today=dateKey(new Date());if(today!==displayedToday){displayedToday=today;render()}}
setInterval(refreshToday,30000);
document.addEventListener("visibilitychange",()=>{if(!document.hidden)refreshToday()});
window.addEventListener("focus",refreshToday);

// First-use guide is separate from personal records, so existing records stay intact.
const guideSteps=[
 {title:'从一个小习惯开始',text:'这是你的习惯手记。添加自己想坚持的事，每天来轻轻打一个勾。',hint:'新用户从空白开始，不会带入别人的习惯。'},
 {title:'一点，就记下今天',text:'点击打卡页的空白处添加习惯；点击日期下面的圆圈打卡，再点一次可以取消。',hint:'点击习惯名称，可以修改名称、颜色或删除习惯。'},
 {title:'习惯和待办，各有位置',text:'「打卡」记录重复的小习惯，「清单」记录要完成的事。点击顶部月份，可以查看其他周，再点「回到本周」返回。'},
 {title:'记得照顾好你的记录',text:'当前版本自动保存在这台设备的这个浏览器里。不同设备的记录互不影响，但不会自动同步。',hint:'清理浏览器数据或使用无痕模式，可能导致记录丢失。当前版本自动保存在这台设备的这个浏览器里，不会自动同步。'}
];
let guideStep=0;
function drawGuide(){const step=guideSteps[guideStep];$('#guideTitle').textContent=step.title;$('#guideText').textContent=step.text;$('#guideHint').textContent=step.hint;$('#guideProgress').textContent=(guideStep+1)+' / '+guideSteps.length;$('#guideBack').hidden=guideStep===0;$('#guideNext').textContent=guideStep===guideSteps.length-1?(data.habits.length?'开始使用':'添加第一个习惯'):'下一步'}
function openGuide(){guideStep=0;drawGuide();$('#guide').showModal()}
function finishGuide(){try{localStorage.setItem('habit-notebook-guide-v1','done')}catch{}$('#guide').close()}
function closeMoreMenu(){const menu=$('#moreMenu');menu.hidden=true;$('#more').setAttribute('aria-expanded','false')}$('#more').onclick=e=>{e.stopPropagation();const menu=$('#moreMenu'),open=menu.hidden;menu.hidden=!open;$('#more').setAttribute('aria-expanded',String(open))};$('#openGuide').onclick=()=>{closeMoreMenu();openGuide()};$('#openData').onclick=()=>{closeMoreMenu();$('#dataDialog').showModal()};document.addEventListener('pointerdown',e=>{if(!$('#topMenu').contains(e.target))closeMoreMenu()});function exportBackup(){const backup={app:'habit-notebook',version:1,exportedAt:new Date().toISOString(),data,colors:readColorStore()};const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='习惯手记备份-'+dateKey(new Date())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已下载')}$('#exportData').onclick=exportBackup;$('#importData').onclick=()=>$('#importFile').click();$('#importFile').onchange=e=>{const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const backup=JSON.parse(reader.result);if(backup?.app!=='habit-notebook'||!Array.isArray(backup.data?.habits)||!backup.data?.checks||!Array.isArray(backup.data?.todos))throw Error();if(!confirm('导入会替换当前浏览器中的习惯与记录，是否继续？'))return;data={habits:backup.data.habits,checks:backup.data.checks,todos:backup.data.todos};if(backup.colors)writeColorStore({saved:Array.isArray(backup.colors.saved)?backup.colors.saved.filter(isSoftColor).slice(0,8):[],recent:Array.isArray(backup.colors.recent)?backup.colors.recent.filter(isSoftColor).slice(0,8):[]});save();$('#dataDialog').close();render();toast('备份已导入')}catch{toast('这不是有效的习惯手记备份文件')}finally{e.target.value=''}};reader.readAsText(file)};
$('#guideSkip').onclick=finishGuide;
$('#guideBack').onclick=()=>{guideStep--;drawGuide()};
$('#guideNext').onclick=()=>{if(guideStep<guideSteps.length-1){guideStep++;drawGuide()}else{finishGuide();if(!data.habits.length){changeView('habits');openEditor()}}};
$('#guide').addEventListener('cancel',finishGuide);
function beginNotebook(){try{if(!hasSavedData&&!localStorage.getItem('habit-notebook-guide-v1'))openGuide()}catch{if(!hasSavedData)openGuide()}}const welcome=$('#welcome');$('#enterApp').onclick=()=>{welcome.classList.add('is-leaving');setTimeout(()=>{welcome.remove();beginNotebook()},360)}

// Blank paper adds a habit; existing controls keep their own actions.
$('#main').addEventListener('click',e=>{
 if(view!=='habits'||$('#editor').open)return;
 if(e.target.closest('.add-habit-hint')){openEditor();return}
 if(e.target.closest('button,input,a,select,textarea,.weekday'))return;
 openEditor();
});
